// museport contract main: <input> <output> sizes...; runs every kernel variant and
// writes each variant's outputs, in order, as raw float32.
int main(int argc, char** argv) {
    setup_main();
    if (argc != 7) {
        fprintf(stderr, "usage: %s <input> <output> B T C NH\n", argv[0]);
        return 2;
    }
    const int B = atoi(argv[3]);
    const int T = atoi(argv[4]);
    const int C = atoi(argv[5]);
    const int NH = atoi(argv[6]);
    FILE* fin = fopen(argv[1], "rb");
    if (!fin) { perror(argv[1]); return 2; }
    float* inp = (float*)malloc(sizeof(float) * (size_t)(B*T*3*C));
    if (fread(inp, sizeof(float), (size_t)(B*T*3*C), fin) != (size_t)(B*T*3*C)) {
        fprintf(stderr, "input too short at inp\n"); return 2;
    }
    fclose(fin);
    FILE* fout = fopen(argv[2], "wb");
    if (!fout) { perror(argv[2]); return 2; }
    float* preatt = (float*)malloc(sizeof(float) * (size_t)B * NH * T * T); float* att = (float*)malloc(sizeof(float) * (size_t)B * NH * T * T);
    float* d_inp;
    cudaCheck(cudaMalloc(&d_inp, sizeof(float) * (size_t)(B*T*3*C)));
    cudaCheck(cudaMemcpy(d_inp, inp, sizeof(float) * (size_t)(B*T*3*C), cudaMemcpyHostToDevice));
    float* out = (float*)malloc(sizeof(float) * (size_t)(B*T*C));
    float* d_out;
    cudaCheck(cudaMalloc(&d_out, sizeof(float) * (size_t)(B*T*C)));
    float* d_stats; float* d_vaccum; float* d_qkvr; float* d_preatt; float* d_att; cudaCheck(cudaMalloc(&d_stats, sizeof(float) * (size_t)B * NH * T)); cudaCheck(cudaMalloc(&d_vaccum, sizeof(float) * (size_t)B * T * C)); cudaCheck(cudaMalloc(&d_qkvr, sizeof(float) * (size_t)B * T * 3 * C)); cudaCheck(cudaMalloc(&d_preatt, sizeof(float) * (size_t)B * NH * T * T)); cudaCheck(cudaMalloc(&d_att, sizeof(float) * (size_t)B * NH * T * T)); cublasCheck(cublasSetMathMode(cublas_handle, CUBLAS_DEFAULT_MATH));
    const int variants[] = {1, 2, 3, 4, 5, 6};
    for (int vi = 0; vi < 6; vi++) {
        const int k = variants[vi];
        cudaCheck(cudaMemset(d_out, 0, sizeof(float) * (size_t)(B*T*C)));
        attention_forward(k, d_out, d_stats, d_vaccum, d_qkvr, d_preatt, d_att, d_inp, B, T, C, NH, 256);
        cudaCheck(cudaGetLastError());
        cudaCheck(cudaDeviceSynchronize());
        cudaCheck(cudaMemcpy(out, d_out, sizeof(float) * (size_t)(B*T*C), cudaMemcpyDeviceToHost));
        fwrite(out, sizeof(float), (size_t)(B*T*C), fout);
    }
    fclose(fout);
    return 0;
}

